}
# POST /api/sheets/{sheetId}/claims/{claimId}/reassign?to=<personId> — a steward moves a DRAFT, OPEN
# or PENDING claim to another person; refused (409, or 423 in a closed period) otherwise.
# A viewer may change nothing: refused before anything is read or written.
guard:
  class: net.officefloor.hq.app.setting.RefuseViewer
  next: before
before:
  class: net.officefloor.hq.app.rollup.TakeRollup
  govern: [ transaction ]
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: move
move:
  class: net.officefloor.hq.app.claim.ReassignClaim
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveReassignment
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimReassigned
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
# POST /api/sheets/{sheetId}/bulk-reassign — move the selected claims to one person together, in list
# order, each by the rules of reassigning one; each that cannot be moved is left as it is. Responds with
# how many were moved and how many refused.
reassign:
  class: net.officefloor.hq.app.claim.BulkReassignClaims
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithBulkReassign

